"""Working offline starters. These are never described as model output."""
import json
from html import escape


def starter(plan, kind="reading"):
    name = plan.get("appName", "我的应用")
    warm = plan.get("palette") == "warm"
    features = plan.get("features", ["collect", "categories", "bookmarks"])
    config = json.dumps({"name": name, "features": features}, ensure_ascii=False).replace("<", "\\u003c")
    style = """*{box-sizing:border-box}body{margin:0;font-family:-apple-system,BlinkMacSystemFont,'PingFang SC',sans-serif;background:var(--bg);color:var(--ink);line-height:1.7}button,input,select,textarea{font:inherit}button{cursor:pointer}button,input,select,textarea{border:1px solid var(--line);border-radius:8px;padding:9px 13px;background:var(--bg);color:var(--ink)}button:hover{filter:brightness(.96)}button:focus-visible,input:focus-visible{outline:2px solid var(--accent);outline-offset:3px}.page{max-width:1050px;margin:auto;padding:0 32px 35px}nav{height:67px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;font-size:13px}nav b{font-weight:500;letter-spacing:2px}nav small{font-size:9px;letter-spacing:1px;opacity:.6}.hero{padding:48px 0 33px;position:relative;overflow:hidden}.eyebrow{font-size:9px;letter-spacing:2px;opacity:.6}h1{font:500 43px/1.35 'Songti SC',Georgia,serif;letter-spacing:1px;margin:15px 0}h1+p{font-size:12px;opacity:.65}.shape{position:absolute;width:100px;height:150px;right:60px;top:45px;background:var(--soft);border-radius:70px 70px 0 0;transform:rotate(-14deg)}.toolbar{display:flex;align-items:center;justify-content:space-between;gap:15px;margin:10px 0 18px}.toolbar h2{font-size:15px;font-weight:500;margin:0}.primary{background:var(--accent);color:var(--bg);border-color:var(--accent)}.filters{display:flex;gap:8px;flex-wrap:wrap;padding:0 0 18px;border-bottom:1px solid var(--line);margin-bottom:20px}.filters button{font-size:11px;border-color:transparent;padding:5px 9px}.filters button.active{background:var(--soft)}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.card{border:1px solid var(--line);border-radius:9px;overflow:hidden;min-width:0;transition:transform .25s,box-shadow .25s}.card:hover{transform:translateY(-3px);box-shadow:0 9px 24px #00000008}.cover{background:var(--soft);padding:23px 20px;min-height:130px;font:32px/1.05 Georgia,serif}.card:nth-child(3n+2) .cover{background:#e4ddd4}.card:nth-child(3n+3) .cover{background:#d8e0d4}.card-body{padding:15px}.meta{display:flex;align-items:center;justify-content:space-between;gap:10px;font-size:9px;opacity:.7}.meta button{border:0;font-size:16px;padding:0 5px}.meta button[aria-pressed=true]{background:var(--soft)}h3{font-size:14px;font-weight:500;margin:10px 0 6px}.card p{font-size:11px;opacity:.65;margin:0 0 15px}.card footer{font-size:10px;opacity:.55}.empty{padding:35px;text-align:center;font-size:12px;opacity:.6}.bottom{font-size:10px;opacity:.5;padding-top:24px;margin-top:28px;border-top:1px solid var(--line)}dialog{border:1px solid var(--line);border-radius:14px;padding:25px;width:min(390px,90vw);background:var(--bg);color:var(--ink)}dialog::backdrop{background:#15151555;backdrop-filter:blur(3px)}dialog h2{font-size:23px;margin:0 0 20px;font-weight:500}label{font-size:11px;display:block;margin-top:13px}label input,label select,label textarea{display:block;width:100%;margin-top:7px}.actions{display:flex;justify-content:flex-end;gap:8px;margin-top:24px}.todo-add{display:flex;gap:10px}.todo-add input{min-width:0;flex:1}.todo-list{list-style:none;padding:0}.todo-item{display:flex;align-items:center;gap:12px;border-bottom:1px solid var(--line);padding:15px 3px;font-size:14px}.todo-item input{accent-color:var(--accent)}.todo-item span{flex:1;overflow-wrap:anywhere}.todo-item.done span{text-decoration:line-through;opacity:.4}.todo-item button{font-size:11px}.project-link{display:block;font-size:11px;color:var(--accent)}[hidden]{display:none!important}@media(max-width:600px){.page{padding:0 19px 25px}h1{font-size:32px}.hero{padding-top:32px}.shape{right:12px;top:44px;width:62px;height:110px;opacity:.7}.grid{grid-template-columns:1fr 1fr;gap:10px}.cover{font-size:24px;min-height:100px;padding:20px 12px}.card-body{padding:11px}h3{font-size:12px}nav small{display:none}.toolbar{margin-top:5px}.toolbar button{font-size:11px}}@media(prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important}}"""
    colors = ("#fffaf4", "#614132", "#ae6942", "#e9d6b7", "#eadfd1") if warm else ("#fafbf7", "#2d422e", "#4c6540", "#dce2cc", "#e4e8dc")
    style = ":root{" + ";".join(f"--{key}:{value}" for key, value in zip(["bg", "ink", "accent", "soft", "line"], colors)) + "}\n" + style
    head = f'<!doctype html>\n<html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{escape(name)}</title><link rel="stylesheet" href="styles.css"></head><body><main class="page"><nav><b>◒ <span id="app-name">{escape(name)}</span></b><small>MADE WITH INTENTION</small></nav>'
    foot = '</main><script src="app.js"></script></body></html>'
    common = f"const config={config};\nconst store=window.FormaStore;\nconst el=(tag,text,cls)=>{{const node=document.createElement(tag);if(text!==undefined)node.textContent=text;if(cls)node.className=cls;return node;}};\n"
    if kind == "todo":
        markup = '<section class="hero"><span class="eyebrow">MAKE SPACE FOR WHAT MATTERS</span><h1>把想法，<br>变成今天的小事。</h1><p>一步一步，做完值得做的事。</p><span class="shape" aria-hidden="true"></span></section><form class="todo-add" id="add-form"><input id="task-input" aria-label="新的待办" placeholder="接下来，想完成什么？" required maxlength="100"><button class="primary">添加事项</button></form><div class="filters"><button data-filter="all" class="active">全部</button><button data-filter="open">待完成</button><button data-filter="done">已完成</button></div><ul class="todo-list" id="tasks"></ul><p class="empty" id="empty" hidden>这里还没有事项，从一件小事开始吧。</p><footer class="bottom" id="count"></footer>'
        script = common + """let tasks=store.get('tasks',[{id:'first',text:'给今天留下一点专注的时间',done:false}]),filter='all';function save(){store.set('tasks',tasks).catch(()=>alert('保存失败，请重试'));}function render(){const list=document.querySelector('#tasks');list.replaceChildren();tasks.filter(task=>filter==='all'||(filter==='done'?task.done:!task.done)).forEach(task=>{const li=el('li',undefined,'todo-item'+(task.done?' done':''));const input=el('input');input.type='checkbox';input.checked=task.done;input.setAttribute('aria-label','完成：'+task.text);input.onchange=()=>{task.done=input.checked;save();render()};const remove=el('button','移除');remove.onclick=()=>{tasks=tasks.filter(t=>t.id!==task.id);save();render()};li.append(input,el('span',task.text),remove);list.append(li)});document.querySelector('#empty').hidden=!!list.children.length;document.querySelector('#count').textContent=`${tasks.filter(t=>t.done).length} / ${tasks.length} 件小事，已经完成。`;}document.querySelector('#add-form').onsubmit=event=>{event.preventDefault();const field=document.querySelector('#task-input');if(!field.value.trim())return;tasks.push({id:crypto.randomUUID(),text:field.value.trim(),done:false});field.value='';save();render()};document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{filter=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b===button));render()});render();"""
    elif kind == "portfolio":
        markup = '<section class="hero"><span class="eyebrow">DESIGNER & CURIOUS HUMAN</span><h1>让作品，<br>替你说话。</h1><p>一些认真做过的小事，一些正在发生的新想法。</p><span class="shape" aria-hidden="true"></span></section><div class="toolbar"><h2>精选作品</h2><button class="primary" id="edit-intro">编辑介绍</button></div><p id="intro"></p><section class="grid" id="projects"></section><footer class="bottom">SELECTED WORK / MADE WITH CARE</footer><dialog id="intro-dialog"><form id="intro-form"><h2>介绍一下自己。</h2><label>个人介绍<textarea name="intro" aria-label="个人介绍" rows="5" maxlength="500"></textarea></label><div class="actions"><button type="button" id="intro-cancel">取消</button><button class="primary">保存介绍</button></div></form></dialog>'
        script = common + """const intro=document.querySelector('#intro');intro.textContent=store.get('intro','你好，我是一位喜欢把复杂问题变简单的创作者。');const samples=[['Quiet spaces','一个让阅读慢下来的空间'],['Good systems','把日常流程整理成清晰的工具'],['Small stories','记录生活中值得留住的片段']];samples.forEach(([title,description])=>{const card=el('article',undefined,'card');card.append(el('div',title,'cover'));const body=el('div',undefined,'card-body');body.append(el('h3',title),el('p',description));card.append(body);document.querySelector('#projects').append(card)});const dialog=document.querySelector('#intro-dialog'),field=dialog.querySelector('textarea');document.querySelector('#edit-intro').onclick=()=>{field.value=intro.textContent;dialog.showModal()};document.querySelector('#intro-cancel').onclick=()=>dialog.close();document.querySelector('#intro-form').onsubmit=event=>{event.preventDefault();intro.textContent=field.value.trim();store.set('intro',intro.textContent).catch(()=>{});dialog.close()};"""
    else:
        markup = '<section class="hero"><span class="eyebrow">YOUR LITTLE CORNER OF THE INTERNET</span><h1>好内容，<br>值得慢慢读。</h1><p>留住偶然遇见的灵感，在自己的节奏里探索。</p><span class="shape" aria-hidden="true"></span></section><div class="toolbar"><h2>我的收藏 <span id="count"></span></h2><button class="primary" id="add">＋ 收藏文章</button></div><div class="filters" id="filters"><button data-filter="all" class="active">全部收藏</button><button data-filter="design">设计灵感</button><button data-filter="technology">技术观察</button><button data-filter="life">生活方式</button><button data-filter="saved">♡ 待读</button></div><section class="grid" id="articles"></section><p class="empty" id="empty" hidden>这里还是空的，留下一点值得读的内容吧。</p><footer class="bottom">少一些稍后再说，多一些此刻的好奇。</footer><dialog id="dialog"><form id="add-form"><h2>留下一点好内容。</h2><label>文章标题<input name="title" aria-label="文章标题" required maxlength="100"></label><label>分类<select name="category"><option value="design">设计灵感</option><option value="technology">技术观察</option><option value="life">生活方式</option></select></label><div class="actions"><button type="button" id="cancel">取消</button><button class="primary">加入收藏</button></div></form></dialog>'
        script = common + """let articles=store.get('articles',[{id:'one',title:'好的设计，懂得留白',category:'design',cover:'Less, but better.',saved:false},{id:'two',title:'把工具变成创作伙伴',category:'technology',cover:'Human × AI',saved:false},{id:'three',title:'给生活一点慢下来的空间',category:'life',cover:'A slower kind of day.',saved:false}]);let filter='all';const categories={design:'设计灵感',technology:'技术观察',life:'生活方式'};function save(){store.set('articles',articles).catch(()=>alert('保存失败，请重试'));}function render(){const grid=document.querySelector('#articles');grid.replaceChildren();articles.filter(a=>filter==='all'||(filter==='saved'?a.saved:a.category===filter)).forEach(a=>{const card=el('article',undefined,'card');card.append(el('div',a.cover,'cover'));const body=el('div',undefined,'card-body'),meta=el('div',undefined,'meta');meta.append(el('span',categories[a.category]));if(config.features.includes('bookmarks')){const mark=el('button',a.saved?'♥':'♡');mark.setAttribute('aria-label',a.saved?'移出待读':'标记为待读');mark.setAttribute('aria-pressed',String(a.saved));mark.onclick=()=>{a.saved=!a.saved;save();render()};meta.append(mark)}body.append(meta,el('h3',a.title),el('p','留给下一次好奇。'),el('footer','我的阅读角落'));card.append(body);grid.append(card)});document.querySelector('#count').textContent=String(articles.length).padStart(2,'0');document.querySelector('#empty').hidden=!!grid.children.length;}document.querySelectorAll('[data-filter]').forEach(button=>{if(button.dataset.filter==='saved')button.hidden=!config.features.includes('bookmarks');else if(button.dataset.filter!=='all')button.hidden=!config.features.includes('categories');button.onclick=()=>{filter=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b===button));render()}});document.querySelector('#filters').hidden=!config.features.includes('categories')&&!config.features.includes('bookmarks');const dialog=document.querySelector('#dialog');document.querySelector('#add').hidden=!config.features.includes('collect');document.querySelector('#add').onclick=()=>dialog.showModal();document.querySelector('#cancel').onclick=()=>dialog.close();document.querySelector('#add-form').onsubmit=event=>{event.preventDefault();const data=new FormData(event.target);if(!data.get('title').trim())return;articles.unshift({id:crypto.randomUUID(),title:data.get('title').trim(),category:data.get('category'),cover:'Something worth reading.',saved:false});save();filter='all';document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter==='all'));render();event.target.reset();dialog.close()};render();"""
    return [
        {"path": "index.html", "text": head + markup + foot},
        {"path": "styles.css", "text": style},
        {"path": "app.js", "text": script},
        {"path": "README.md", "text": f"# {name}\n\n本地模板构建，非模型生成。\n\n界面入口 index.html；样式 styles.css；交互 app.js。\n应用数据通过 FormaStore 保存到项目数据库。\n"},
    ]
